class Swiper{constructor(selector,options={}){this.el=typeof selector==="string"?document.querySelector(selector):selector;if(!this.el)return;this.options=options;this.wrapper=this.el.querySelector(".swiper-wrapper");this.original=[...this.wrapper.children];this.index=0;this.dragging=false;this.startX=0;this.currentX=0;this.timer=null;this.setup();this.bind();this.go(0,false);this.autoplay()}setup(){if(this.options.loop){this.original.forEach((s)=>this.wrapper.appendChild(s.cloneNode(true)))}this.slides=[...this.wrapper.children];this.resize=()=>{const per=this.perView();this.slideW=this.el.clientWidth/per;this.slides.forEach((s)=>{s.style.width=this.slideW+"px"});this.go(this.index,false)};window.addEventListener("resize",this.resize);this.resize()}perView(){const w=innerWidth;const cfg=this.options.breakpoints||{};let per=this.options.slidesPerView||1;Object.keys(cfg).map(Number).sort((a,b)=>a-b).forEach((bp)=>{if(w>=bp&&cfg[bp].slidesPerView)per=cfg[bp].slidesPerView});return per}bind(){this.el.addEventListener("pointerdown",(e)=>{this.dragging=true;this.startX=e.clientX;this.currentX=e.clientX;this.wrapper.style.transition="none";this.el.setPointerCapture(e.pointerId)});this.el.addEventListener("pointermove",(e)=>{if(!this.dragging)return;this.currentX=e.clientX;this.wrapper.style.transform=`translateX(${-(this.index*this.slideW)+(this.currentX-this.startX)}px)`});this.el.addEventListener("pointerup",()=>{if(!this.dragging)return;this.dragging=false;this.wrapper.style.transition="transform .45s ease";const delta=this.currentX-this.startX;if(Math.abs(delta)>45)this.go(this.index+(delta<0?1:-1));else this.go(this.index)});this.el.querySelector(".swiper-button-next")?.addEventListener("click",()=>this.go(this.index+1));this.el.querySelector(".swiper-button-prev")?.addEventListener("click",()=>this.go(this.index-1))}go(i,animate=true){if(!this.slides.length)return;const max=this.options.loop?this.original.length:this.slides.length-this.perView();if(i>=this.original.length&&this.options.loop){this.index=0}else if(i<0&&this.options.loop){this.index=this.original.length-1}else{this.index=Math.max(0,Math.min(i,max))}if(!animate)this.wrapper.style.transition="none";this.wrapper.style.transform=`translateX(${-this.index*this.slideW}px)`;if(!animate)requestAnimationFrame(()=>{this.wrapper.style.transition="transform .45s ease"})}autoplay(){const delay=this.options.autoplay?.delay;if(!delay)return;clearInterval(this.timer);this.timer=setInterval(()=>this.go(this.index+1),delay);this.el.addEventListener("mouseenter",()=>clearInterval(this.timer));this.el.addEventListener("mouseleave",()=>this.autoplay(),{once:true})}}
